//! Loader for the shared conformance vectors (`conformance/vectors/*.txt`) generated by
//! `python/tests/gen_vectors.py`.
#![allow(dead_code)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use openpaykernel::apdu::{Reader, TransmissionError};
use openpaykernel::{
    AidConfig, AppCandidate, Capk, CapkStore, ContactHost, Environment, OnlineResponse, TerminalConfig, Transaction,
};

pub fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex")).collect()
}

fn field<'a>(line: &'a str, key: &str) -> Option<&'a str> {
    line.split_whitespace().find_map(|kv| kv.strip_prefix(key).and_then(|r| r.strip_prefix('=')))
}

#[derive(Debug, Clone, Default)]
pub struct HostScript {
    pub pins: Vec<String>,
    pub online: bool,
    pub approved: bool,
    pub arc: [u8; 2],
    pub iad: Option<Vec<u8>>,
    pub scripts: Vec<u8>,
}

pub struct Vector {
    pub name: String,
    pub contact: bool,
    pub terminal: TerminalConfig,
    pub capks: Vec<Capk>,
    pub aids: Vec<AidConfig>,
    pub txn: Transaction,
    pub host: HostScript,
    pub apdus: Vec<(Vec<u8>, Vec<u8>)>,
    pub status: u8,
    pub cvm: u8,
    pub tags: Vec<(u32, Vec<u8>)>,
}

pub fn vector_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../conformance/vectors")
}

pub fn load_all() -> Vec<Vector> {
    let mut paths: Vec<_> = std::fs::read_dir(vector_dir()).expect("vector dir").map(|e| e.unwrap().path()).collect();
    paths.sort();
    paths.iter().filter(|p| p.extension().is_some_and(|e| e == "txt")).map(|p| load(p)).collect()
}

pub fn load(path: &Path) -> Vector {
    let text = std::fs::read_to_string(path).expect("read vector");
    let mut v = Vector {
        name: String::new(),
        contact: false,
        terminal: TerminalConfig::default(),
        capks: Vec::new(),
        aids: Vec::new(),
        txn: Transaction::new(0),
        host: HostScript::default(),
        apdus: Vec::new(),
        status: 0,
        cvm: 0,
        tags: Vec::new(),
    };
    let mut pending_c: Option<Vec<u8>> = None;
    for line in text.lines() {
        let (kw, _) = line.split_once(' ').unwrap_or((line, ""));
        let l = &format!(" {line}")[..];
        let f = |k: &str| field(l, k).unwrap_or_else(|| panic!("{}: missing {k} in {line}", path.display()));
        match kw {
            "SCENARIO" => v.name = line[9..].trim().to_string(),
            "MODE" => v.contact = line.ends_with("contact"),
            "TERM" => {
                v.terminal.terminal_type = u8::from_str_radix(f("type"), 16).unwrap();
                v.terminal.capabilities.copy_from_slice(&unhex(f("caps")));
                v.terminal.additional_capabilities.copy_from_slice(&unhex(f("addcaps")));
                v.terminal.country_code.copy_from_slice(&unhex(f("country")));
            }
            "CAPK" => {
                let rid: [u8; 5] = unhex(f("rid")).try_into().unwrap();
                let idx = u8::from_str_radix(f("index"), 16).unwrap();
                v.capks.push(Capk::new(rid, idx, unhex(f("mod")), unhex(f("exp")), f("expiry")));
            }
            "AID" => {
                let mut a = AidConfig::new(&unhex(f("aid")));
                a.kernel_id = f("kernel").parse().unwrap();
                a.partial_match = f("partial") == "1";
                a.floor_limit = f("floor").parse().unwrap();
                a.tac_default.copy_from_slice(&unhex(f("tac_default")));
                a.tac_denial.copy_from_slice(&unhex(f("tac_denial")));
                a.tac_online.copy_from_slice(&unhex(f("tac_online")));
                a.ttq.copy_from_slice(&unhex(f("ttq")));
                a.default_ddol = unhex(f("ddol"));
                a.app_version.copy_from_slice(&unhex(f("version")));
                a.cl_transaction_limit = field(l, "cl_limit").map(|x| x.parse().unwrap());
                a.cvm_required_limit = field(l, "cvm_limit").map(|x| x.parse().unwrap());
                if let Some(extra) = field(l, "extra") {
                    for kv in extra.split(',') {
                        let (t, val) = kv.split_once(':').unwrap();
                        a.extra.insert(u32::from_str_radix(t, 16).unwrap(), unhex(val));
                    }
                }
                v.aids.push(a);
            }
            "TXN" => {
                v.txn.amount = f("amount").parse().unwrap();
                v.txn.amount_other = f("other").parse().unwrap();
                v.txn.txn_type = u8::from_str_radix(f("type"), 16).unwrap();
                v.txn.date = f("date").to_string();
                v.txn.time = f("time").to_string();
                v.txn.currency_code.copy_from_slice(&unhex(f("currency")));
                v.txn.sequence_counter = f("seq").parse().unwrap();
            }
            "HOST" => {
                let pins = f("pins");
                if pins != "-" {
                    v.host.pins = pins.split(',').map(String::from).collect();
                }
                v.host.online = f("online") == "1";
                v.host.approved = f("approved") == "1";
                if f("arc") != "-" {
                    v.host.arc.copy_from_slice(&unhex(f("arc")));
                }
                if f("iad") != "-" {
                    v.host.iad = Some(unhex(f("iad")));
                }
                if f("scripts") != "-" {
                    v.host.scripts = unhex(f("scripts"));
                }
            }
            "C" => pending_c = Some(unhex(&line[2..])),
            "R" => v.apdus.push((pending_c.take().expect("R without C"), unhex(&line[2..]))),
            "EXPECT" => {
                v.status = f("status").parse().unwrap();
                v.cvm = f("cvm").parse().unwrap();
            }
            "EXPECT_TAG" => {
                let mut it = line.split_whitespace().skip(1);
                let tag = u32::from_str_radix(it.next().unwrap(), 16).unwrap();
                v.tags.push((tag, unhex(it.next().unwrap())));
            }
            _ => {}
        }
    }
    v
}

/// Deterministic RNG used by the generator: consecutive byte values starting at 0x11.
pub fn counter_rng() -> openpaykernel::config::RngFn {
    let mut state: u8 = 0x11;
    Box::new(move |buf: &mut [u8]| {
        for b in buf.iter_mut() {
            *b = state;
            state = state.wrapping_add(1);
        }
    })
}

pub fn environment(v: &Vector) -> Environment {
    let mut store = CapkStore::new();
    for k in &v.capks {
        store.add(k.clone()).unwrap();
    }
    Environment::new(v.terminal.clone(), v.aids.clone(), store, counter_rng())
}

/// Replays the card side; records whether the kernel's commands diverge from the vector.
pub struct Replay {
    pub apdus: Vec<(Vec<u8>, Vec<u8>)>,
    pub pos: usize,
    pub mismatch: Option<String>,
    /// Fuzz mode: corrupt responses with this PRNG state instead of checking commands.
    pub fuzz: Option<u32>,
}

impl Replay {
    pub fn new(apdus: Vec<(Vec<u8>, Vec<u8>)>) -> Self {
        Replay { apdus, pos: 0, mismatch: None, fuzz: None }
    }

    fn rand(&mut self) -> u32 {
        let s = self.fuzz.as_mut().unwrap();
        *s = s.wrapping_mul(1103515245).wrapping_add(12345);
        *s >> 8
    }
}

impl Reader for Replay {
    fn transmit(&mut self, capdu: &[u8]) -> Result<Vec<u8>, TransmissionError> {
        if self.fuzz.is_some() {
            let i = if self.pos < self.apdus.len() {
                self.pos += 1;
                self.pos - 1
            } else {
                (self.rand() as usize) % self.apdus.len()
            };
            let mut r = self.apdus[i].1.clone();
            if self.rand() % 6 != 0 {
                return Ok(r); // corrupt about one response in six, so transactions get deep
            }
            for _ in 0..1 + self.rand() % 3 {
                if r.len() > 2 {
                    let at = self.rand() as usize % (r.len() - 2);
                    r[at] ^= 1 << (self.rand() % 8);
                }
            }
            if self.rand() % 8 == 0 && r.len() > 3 {
                let cut = self.rand() as usize % (r.len() - 2);
                let sw = r[r.len() - 2..].to_vec();
                r.truncate(cut);
                r.extend_from_slice(&sw);
            }
            return Ok(r);
        }
        let Some((c, r)) = self.apdus.get(self.pos).cloned() else {
            self.mismatch.get_or_insert_with(|| format!("unexpected extra command {}", hex(capdu)));
            return Ok(vec![0x6F, 0x00]);
        };
        if c != capdu && self.mismatch.is_none() {
            self.mismatch =
                Some(format!("command {} differs\n  expected {}\n  sent     {}", self.pos, hex(&c), hex(capdu)));
        }
        self.pos += 1;
        Ok(r)
    }
}

pub fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02X}")).collect()
}

pub struct ScriptedHost {
    pub script: HostScript,
    next_pin: usize,
}

impl ScriptedHost {
    pub fn new(script: HostScript) -> Self {
        ScriptedHost { script, next_pin: 0 }
    }
}

impl ContactHost for ScriptedHost {
    fn choose_application(&mut self, _candidates: &[AppCandidate]) -> Option<usize> {
        Some(0)
    }
    fn enter_pin(&mut self, _online: bool, _tries_left: Option<u8>) -> Option<String> {
        let p = self.script.pins.get(self.next_pin).cloned();
        self.next_pin += 1;
        p
    }
    fn go_online(&mut self, _data: &BTreeMap<u32, Vec<u8>>) -> Option<OnlineResponse> {
        self.script.online.then(|| OnlineResponse {
            approved: self.script.approved,
            arc: self.script.arc,
            issuer_auth_data: self.script.iad.clone(),
            scripts: self.script.scripts.clone(),
        })
    }
}
